values
  ('3ee11dfa-0396-490c-9b9b-f6fd187b670e', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Writing for the Ear', 'Broadcast writing begins with language that can be understood the first time it is heard. This section trains students to write conversational, precise, tightly voiced copy that respects time, sound, and audience attention.', 0),
  ('7d7ffb4c-215c-42e5-8296-fb8e30bfc070', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '3ee11dfa-0396-490c-9b9b-f6fd187b670e', 'subtopic'::public.curated_course_node_type, 'Conversational broadcast style', 'Students learn why spoken news copy must be shorter, clearer, and more direct than print copy.', 0),
