  ('b92a7660-f99c-48fb-a2a3-4924e7dec733', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '65aaeaaa-9476-462d-9a29-b7835fde7543', 'concept'::public.curated_course_node_type, 'Teases and tosses', null, 3),
  ('8d5a5453-f63d-4d2f-9490-dfb17bc241e0', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Broadcast Story Structure and Script Formats', 'Broadcast stories are built through words, pictures, sound, sequencing, and timing. Students learn the professional script forms that turn reporting into clear, producible segments.', 1),
