  ('e79d6005-71c4-4b6a-a2f3-6f5e999a52ae', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '8d5a5453-f63d-4d2f-9490-dfb17bc241e0', 'subtopic'::public.curated_course_node_type, 'Professional scripting conventions', 'The goal is fluency with scripts that anchors, producers, editors, and control-room teams can actually use.', 2),
