  ('5c723215-254f-4829-a22c-30d13e005c87', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'e79d6005-71c4-4b6a-a2f3-6f5e999a52ae', 'concept'::public.curated_course_node_type, 'Timing marks', null, 3),
  ('11c8b43d-5650-4ba7-8e76-a0a938e880f9', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Voice, Presence, and On-Air Delivery', 'Credible broadcast delivery combines breath, vocal control, presence, pacing, and ethical restraint. Students learn to sound natural while communicating urgency, care, and authority.', 2),
  ('57173ccd-863e-4747-9d25-08b2d39e50d2', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '11c8b43d-5650-4ba7-8e76-a0a938e880f9', 'subtopic'::public.curated_course_node_type, 'Voice fundamentals', 'Students practice breath support, articulation, emphasis, and pacing so their delivery strengthens meaning.', 0),
