  ('527f7239-6848-43f8-9526-63436796895d', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '57173ccd-863e-4747-9d25-08b2d39e50d2', 'concept'::public.curated_course_node_type, 'Pace and pause', null, 3),
  ('73ec0b25-b6d8-4c57-b866-b876d248f26e', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '11c8b43d-5650-4ba7-8e76-a0a938e880f9', 'subtopic'::public.curated_course_node_type, 'Camera and microphone presence', 'Students learn how posture, eye line, energy, and listening change across studio, field, and audio-only contexts.', 1);
