  ('4a315b48-8b0b-4ae1-8249-53c90b81d8c6', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'dc18bde6-5807-41f2-8ac9-ea9fc9f1d15f', 'concept'::public.curated_course_node_type, 'Corrections on air', null, 3),
  ('b2ec513b-1ab7-49c4-8dcb-4e79a9d58455', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Audio Reporting and Podcast Fundamentals', 'World-class broadcast training now requires deep audio literacy. This section builds skills in recording, writing, editing, and shaping sound-rich stories for radio, podcast, and digital listening.', 3),
  ('302912dd-4d81-4e60-99ab-2e08e6ba8773', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'b2ec513b-1ab7-49c4-8dcb-4e79a9d58455', 'subtopic'::public.curated_course_node_type, 'Field audio gathering', 'Students learn to capture clean interviews, room tone, natural sound, ambience, and scene-setting audio.', 0),
