  ('84a14569-391a-4faf-8be6-9b68d5918765', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '302912dd-4d81-4e60-99ab-2e08e6ba8773', 'concept'::public.curated_course_node_type, 'Monitoring', null, 2),
  ('c4b11f35-d627-4782-8ca5-5c747daf5cae', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '302912dd-4d81-4e60-99ab-2e08e6ba8773', 'concept'::public.curated_course_node_type, 'Room tone', null, 3),
