  ('97844adf-e069-4eec-a0ac-38e17c702d27', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '50853aa2-f53e-4cea-a701-81f4555fc1be', 'concept'::public.curated_course_node_type, 'Series identity', null, 3),
  ('1fae1116-2bfb-4a43-9d12-683b115b2c15', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Field Reporting, Standups, and Mobile Journalism', 'Field reporters must gather reliable information, usable media, and audience-facing explanations in unpredictable conditions. Students learn to work safely, independently, and professionally outside the classroom newsroom.', 4),
  ('1892b215-a01a-4d01-bd88-325bee07d1d1', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1fae1116-2bfb-4a43-9d12-683b115b2c15', 'subtopic'::public.curated_course_node_type, 'Field preparation', 'Students plan assignments so they arrive with enough background, contacts, gear, permissions, and fallback options.', 0),
  ('2d302583-8008-427b-a6d8-45a1be47fe56', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1892b215-a01a-4d01-bd88-325bee07d1d1', 'concept'::public.curated_course_node_type, 'Pre-interviews', null, 0),
  ('c92ce736-d7e6-4a72-ae19-b2bc8bfc0671', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1892b215-a01a-4d01-bd88-325bee07d1d1', 'concept'::public.curated_course_node_type, 'Location scouting', null, 1),
  ('843cc52c-9d9d-4da8-ae0b-298cd9f17bf6', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1892b215-a01a-4d01-bd88-325bee07d1d1', 'concept'::public.curated_course_node_type, 'Gear checklists', null, 2),
  ('546cc92f-abb6-479c-be6f-5051badf0dbb', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1892b215-a01a-4d01-bd88-325bee07d1d1', 'concept'::public.curated_course_node_type, 'Safety plans', null, 3),
  ('9c4fe878-7f8f-4f76-b3ca-52635472fdb6', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1fae1116-2bfb-4a43-9d12-683b115b2c15', 'subtopic'::public.curated_course_node_type, 'Standups and live shots', 'Students learn when reporter presence adds value and how to write standups that advance the story.', 1),
  ('e79d5279-f4c4-4b33-b142-225e4e482915', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '9c4fe878-7f8f-4f76-b3ca-52635472fdb6', 'concept'::public.curated_course_node_type, 'Bridge standups', null, 0),
