  ('3e59442a-e9ab-4361-b7cc-787db13cfbbf', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '9c4fe878-7f8f-4f76-b3ca-52635472fdb6', 'concept'::public.curated_course_node_type, 'Live intros', null, 2),
  ('85370537-f5c4-4016-97eb-a721558b2cd6', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '9c4fe878-7f8f-4f76-b3ca-52635472fdb6', 'concept'::public.curated_course_node_type, 'Live tags', null, 3),
  ('314c9ffd-0528-40c3-98f5-5cf71d853e32', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1fae1116-2bfb-4a43-9d12-683b115b2c15', 'subtopic'::public.curated_course_node_type, 'Mobile journalism practice', 'The section emphasizes responsible solo reporting with phones and lightweight kits.', 2),
  ('1515d58c-45a2-4618-907c-e089ed70c2aa', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '314c9ffd-0528-40c3-98f5-5cf71d853e32', 'concept'::public.curated_course_node_type, 'Phone video settings', null, 0),
