insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('8ddfc2ff-5556-4ad0-a95f-b0ca2cd8bb92', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '314c9ffd-0528-40c3-98f5-5cf71d853e32', 'concept'::public.curated_course_node_type, 'File transfer', null, 3),
  ('9d422b23-8e0a-42a4-97c4-06abb3742720', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Broadcast Interviewing and Source Development', 'Broadcast interviews must be accurate, ethical, concise, and emotionally intelligent. Students learn to prepare questions, listen actively, gather usable sound, and build sources beyond a single assignment.', 5),
  ('1f0eb0a2-bc9d-4331-92ec-67847d8fb0bd', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '9d422b23-8e0a-42a4-97c4-06abb3742720', 'subtopic'::public.curated_course_node_type, 'Interview preparation', 'Students learn how background research and source mapping improve both fairness and story quality.', 0),
  ('011b1b72-ae5b-4984-a912-b01b5c4eeaf1', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1f0eb0a2-bc9d-4331-92ec-67847d8fb0bd', 'concept'::public.curated_course_node_type, 'Source lists', null, 0),
