  ('68ffd6cc-c62f-4553-b359-800ecef2b027', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '1f0eb0a2-bc9d-4331-92ec-67847d8fb0bd', 'concept'::public.curated_course_node_type, 'Document preparation', null, 3),
