  ('3b6c9ac8-1845-45f6-9805-ab3e9e6f5c83', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '7a56a1f5-2faf-4525-b8b2-f5cef7d1ba5c', 'concept'::public.curated_course_node_type, 'Follow-up questions', null, 0),
