  ('94319311-70f5-47ec-b118-20bc19213e91', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '7a56a1f5-2faf-4525-b8b2-f5cef7d1ba5c', 'concept'::public.curated_course_node_type, 'Nonverbal cues', null, 2),
  ('e816b665-8f0a-43f8-9565-f142ce37e7d0', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '7a56a1f5-2faf-4525-b8b2-f5cef7d1ba5c', 'concept'::public.curated_course_node_type, 'Clean soundbites', null, 3),
  ('227d5ca5-b84f-4d41-9384-8be2586920f2', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '9d422b23-8e0a-42a4-97c4-06abb3742720', 'subtopic'::public.curated_course_node_type, 'Ethical source relationships', 'The point is to protect independence while treating sources, victims, officials, and community members with dignity.', 2),
  ('5954be1e-e4fb-421b-93cd-86b1df7506dd', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '227d5ca5-b84f-4d41-9384-8be2586920f2', 'concept'::public.curated_course_node_type, 'Power dynamics', null, 0),
  ('dc5de7f6-4536-4adc-af45-eec0d59011dd', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '227d5ca5-b84f-4d41-9384-8be2586920f2', 'concept'::public.curated_course_node_type, 'Trauma-informed practice', null, 1),
  ('132d0069-af07-4855-a79d-ea8425c1b86b', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '227d5ca5-b84f-4d41-9384-8be2586920f2', 'concept'::public.curated_course_node_type, 'Vulnerable sources', null, 2),
  ('57d79f7d-fadc-4bdd-81d1-39205ac6b371', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '227d5ca5-b84f-4d41-9384-8be2586920f2', 'concept'::public.curated_course_node_type, 'Transparency about use', null, 3),
  ('e6430776-54bb-4506-aea3-c8fd6c8a9785', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Video Shooting, Sequencing, and Editing', 'Strong broadcast video is reported, sequenced, and edited, not merely recorded. Students learn visual grammar, news shooting discipline, and editing choices that clarify rather than manipulate.', 6),
  ('c57cef51-97b0-4ff8-bc05-c3776d49e4e6', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'e6430776-54bb-4506-aea3-c8fd6c8a9785', 'subtopic'::public.curated_course_node_type, 'Visual reporting basics', 'Students learn to think in shots that answer journalistic questions and show evidence.', 0),
  ('afa727e0-8241-4236-bc88-937dd8503d45', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'c57cef51-97b0-4ff8-bc05-c3776d49e4e6', 'concept'::public.curated_course_node_type, 'Wide, medium, tight', null, 0),
  ('686d6d82-19b1-4117-81af-312984a0d357', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'c57cef51-97b0-4ff8-bc05-c3776d49e4e6', 'concept'::public.curated_course_node_type, 'Action/reaction', null, 1),
  ('cc56651e-0999-400e-8942-7f0259615533', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'c57cef51-97b0-4ff8-bc05-c3776d49e4e6', 'concept'::public.curated_course_node_type, 'Cutaways', null, 2),
  ('87d21503-cfb2-42bf-b11e-015999c62840', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'c57cef51-97b0-4ff8-bc05-c3776d49e4e6', 'concept'::public.curated_course_node_type, 'Sequences', null, 3),
  ('5fe8e651-c3e9-4bbf-83f7-881d4f1a01a1', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'e6430776-54bb-4506-aea3-c8fd6c8a9785', 'subtopic'::public.curated_course_node_type, 'Editing for meaning', 'Students practice assembling video so story logic, continuity, and ethical context remain intact.', 1),
  ('547d9166-2508-4906-a973-8ebe4156c23b', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '5fe8e651-c3e9-4bbf-83f7-881d4f1a01a1', 'concept'::public.curated_course_node_type, 'Shot order', null, 0),
