  ('30314b31-cce1-46ad-b3b6-dfe0fb9ecb9b', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '5fe8e651-c3e9-4bbf-83f7-881d4f1a01a1', 'concept'::public.curated_course_node_type, 'Jump cuts', null, 2),
  ('92f46a38-990d-40da-9c1d-d5b2cba76b80', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '5fe8e651-c3e9-4bbf-83f7-881d4f1a01a1', 'concept'::public.curated_course_node_type, 'Avoiding misleading edits', null, 3),
