  ('9833a225-3369-45fc-811b-97731ba80a05', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '70c946ae-6657-48f5-9ec5-ac4a0d3b0e69', 'concept'::public.curated_course_node_type, 'Audio levels', null, 0),
