  ('392f18e1-ccf5-4998-9d7e-f64e3bce07e2', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '70c946ae-6657-48f5-9ec5-ac4a0d3b0e69', 'concept'::public.curated_course_node_type, 'Captions', null, 2),
  ('e7beb44d-4e65-49b5-beb5-35ae91548a0a', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '70c946ae-6657-48f5-9ec5-ac4a0d3b0e69', 'concept'::public.curated_course_node_type, 'File naming and export settings', null, 3),
  ('726e3e86-af00-4893-b11b-2353d46dcd6a', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Radio Packages, Sound Design, and Narrative Audio', 'Radio and audio journalism sharpen a student''s ear for scene, pacing, texture, and accountability. This section explores deeper radio craft and narrative audio storytelling.', 7),
  ('cd5262b4-8b99-4470-9c0f-c92412b79475', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '726e3e86-af00-4893-b11b-2353d46dcd6a', 'subtopic'::public.curated_course_node_type, 'Radio package structure', 'Students build wraps and features that combine narration, actuality, ambience, and clear attribution.', 0),
  ('c218e746-b4d5-4f3a-b6e4-870f7dcb0d65', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'cd5262b4-8b99-4470-9c0f-c92412b79475', 'concept'::public.curated_course_node_type, 'Host ledes', null, 0),
  ('f696a61b-afb3-46fd-bc54-a96e8eb1a958', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'cd5262b4-8b99-4470-9c0f-c92412b79475', 'concept'::public.curated_course_node_type, 'Reporter tracks', null, 1),
  ('2b58a700-7a33-411f-9bab-a5a789719934', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'cd5262b4-8b99-4470-9c0f-c92412b79475', 'concept'::public.curated_course_node_type, 'Actuality selection', null, 2),
  ('83a6d02e-48ba-448d-b31c-d9a9e71ba1ba', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'cd5262b4-8b99-4470-9c0f-c92412b79475', 'concept'::public.curated_course_node_type, 'Tags', null, 3),
  ('d41fe722-e6e2-4fc8-957b-d66b6fe01431', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', '726e3e86-af00-4893-b11b-2353d46dcd6a', 'subtopic'::public.curated_course_node_type, 'Sound design ethics', 'Students learn where production polish helps comprehension and where it risks distorting reality.', 1);
