  ('4fdcc170-596f-4617-9140-b937133d9480', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'a94f4138-5764-4f48-8cd7-e6f15c0065a7', 'concept'::public.curated_course_node_type, 'Tension and release', null, 2),
  ('2c704ea6-7dd2-486e-96e2-8e632f2442c7', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', 'a94f4138-5764-4f48-8cd7-e6f15c0065a7', 'concept'::public.curated_course_node_type, 'Ending with context', null, 3),
  ('5aa1cbac-8ca8-4160-97da-19b7ef6a4ef7', 'e5f6a7b8-9c0d-4e11-8f01-1a2b3c4d5e21', null, 'topic'::public.curated_course_node_type, 'Anchoring and Studio Performance', 'Anchoring is an editorial role as much as an on-camera role. Students learn to present copy, listen through the control room, recover from changes, and maintain credibility during a live show.', 8),
